from pathlib import Path
p=Path('/mnt/data/reptrack_v9')
html=(p/'index.html').read_text()
html=html.replace('<p class="eyebrow">Твій тренувальний журнал</p>\n        <h1>RepTrack</h1>', '<p class="eyebrow">Твій тренувальний журнал</p>\n        <h1>RepTrack</h1>\n        <span class="network-status" id="network-status">Онлайн</span>')
html=html.replace('''<label class="field-label">Іконка<input id="category-icon" type="text" maxlength="2" placeholder="◉" /></label>\n        <button class="primary-btn" id="save-category">Створити розділ</button>''', '''<label class="field-label">Іконка</label>\n        <div class="icon-picker" id="category-icon-picker"></div>\n        <input id="category-icon" type="hidden" value="icons/custom.svg" />\n        <button class="primary-btn" id="save-category">Створити розділ</button>''')
html=html.replace('''<label class="field-label">Іконка<input id="exercise-icon" type="text" maxlength="2" placeholder="↕" /></label>\n        <button class="primary-btn" id="save-exercise">Створити вправу</button>''', '''<label class="field-label">Іконка</label>\n        <div class="icon-picker" id="exercise-icon-picker"></div>\n        <input id="exercise-icon" type="hidden" value="icons/custom.svg" />\n        <button class="primary-btn" id="save-exercise">Створити вправу</button>''')
html=html.replace('''  <!-- Builder modal -->''', '''  <!-- Exercise history modal -->\n  <div class="modal-backdrop hidden" id="history-modal" role="dialog" aria-modal="true" aria-labelledby="history-title">\n    <div class="modal slide-up wide-modal">\n      <button class="modal-close" id="history-close" aria-label="Закрити">×</button>\n      <p class="eyebrow">Історія вправи</p>\n      <h2 id="history-title">Вправа</h2>\n      <p class="muted" id="history-subtitle"></p>\n      <div class="history-stats" id="history-stats"></div>\n      <div class="history-list" id="history-list"></div>\n    </div>\n  </div>\n\n  <!-- Builder modal -->''')
(p/'index.html').write_text(html)
